CREATE TABLE IF NOT EXISTS families (id TEXT PRIMARY KEY, name TEXT NOT NULL, budget INTEGER NOT NULL CHECK(budget>0), plan TEXT NOT NULL DEFAULT 'Family', demo INTEGER NOT NULL DEFAULT 1, created TEXT NOT NULL);
CREATE TABLE drivers (id TEXT PRIMARY KEY, family TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','driver')));
CREATE TABLE cars (id TEXT PRIMARY KEY, family TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, name TEXT NOT NULL, fuel TEXT NOT NULL, mpg INTEGER NOT NULL CHECK(mpg>0));
CREATE TABLE sessions (token TEXT PRIMARY KEY, family TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, driver TEXT NOT NULL REFERENCES drivers(id) ON DELETE CASCADE, expires TEXT NOT NULL);
CREATE TABLE invites (id TEXT PRIMARY KEY, family TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, driver TEXT NOT NULL REFERENCES drivers(id) ON DELETE CASCADE, expires TEXT NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE periods (id TEXT PRIMARY KEY, family TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, month TEXT NOT NULL, budget INTEGER NOT NULL CHECK(budget>0), UNIQUE(family, month));
CREATE TABLE stations (id TEXT PRIMARY KEY, family TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, name TEXT NOT NULL, address TEXT NOT NULL, gasoline INTEGER NOT NULL, diesel INTEGER NOT NULL, mile INTEGER NOT NULL);
CREATE TABLE offers (id TEXT PRIMARY KEY, family TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, name TEXT NOT NULL, partner TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('lock','prebuy')), fuel TEXT NOT NULL, grade TEXT NOT NULL, cap INTEGER NOT NULL, volume INTEGER NOT NULL, fee INTEGER NOT NULL, service INTEGER NOT NULL, deadline TEXT NOT NULL, starts TEXT NOT NULL, ends TEXT NOT NULL, allowed TEXT NOT NULL, scope TEXT NOT NULL, terms TEXT NOT NULL, version TEXT NOT NULL, source TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','published','expired','suspended')));
CREATE TABLE contracts (id TEXT PRIMARY KEY, family TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, offer TEXT NOT NULL REFERENCES offers(id), code TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK(status IN ('requested','active','expired','cancelled')), available INTEGER NOT NULL CHECK(available>=0), reserved INTEGER NOT NULL CHECK(reserved>=0), used INTEGER NOT NULL CHECK(used>=0), activated TEXT, UNIQUE(family,offer));
CREATE TABLE goals (id TEXT PRIMARY KEY, family TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, name TEXT NOT NULL, target INTEGER NOT NULL CHECK(target>0), auto INTEGER NOT NULL);
CREATE UNIQUE INDEX one_round_up_goal ON goals(family) WHERE auto=1;
CREATE TABLE purchases (id TEXT PRIMARY KEY, family TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, driver TEXT NOT NULL REFERENCES drivers(id), station TEXT NOT NULL REFERENCES stations(id), contract TEXT REFERENCES contracts(id), fuel TEXT NOT NULL, grade TEXT NOT NULL, volume INTEGER NOT NULL CHECK(volume>0), covered INTEGER NOT NULL CHECK(covered>=0 AND covered<=volume), pump INTEGER NOT NULL, amount INTEGER NOT NULL, benefit INTEGER NOT NULL, market INTEGER NOT NULL, reward INTEGER NOT NULL, reward_status TEXT NOT NULL, status TEXT NOT NULL, at TEXT NOT NULL, source TEXT NOT NULL, fingerprint TEXT NOT NULL, round_up INTEGER NOT NULL DEFAULT 0, goal TEXT REFERENCES goals(id), UNIQUE(family,fingerprint));
CREATE INDEX purchases_family_at ON purchases(family,at);
CREATE TABLE requests (family TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, key TEXT NOT NULL, payload TEXT NOT NULL, purchase TEXT NOT NULL REFERENCES purchases(id), PRIMARY KEY(family,key));
CREATE TABLE receipts (id TEXT PRIMARY KEY, family TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, purchase TEXT NOT NULL REFERENCES purchases(id), hash TEXT NOT NULL, name TEXT NOT NULL, mime TEXT NOT NULL, content BLOB NOT NULL, UNIQUE(family,hash));
CREATE TABLE claims (id TEXT PRIMARY KEY, family TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, purchase TEXT NOT NULL UNIQUE REFERENCES purchases(id), amount INTEGER NOT NULL CHECK(amount>0), status TEXT NOT NULL, at TEXT NOT NULL);
